import React from 'react';
import './AboutMe.css';
const AboutMe = () => {
    return (
        <section id="aboutme">
            <div className="container">
            <div className="text">
                <h1>About Me</h1>
                <p>I'm a web developer who loves to create sleek, user-friendly websites. When I'm not coding, you'll find me exploring the latest tech trends or playing video games. <br></br>Graduated from the University of San Jose-Recoletos and had a blast interning at Accenture, where I built cool automation solutions from scratch. Now, I'm ready to take on the world one line of code at a time!</p>
            </div>
            <div className='image'>
            </div>
            </div>
        </section>
    );
};

export default AboutMe;
